-- OLLIN: matriz de transición DETERMINISTA v2 (SQL Server)
-- Ejecutar completo en SSMS. Borra las tablas anteriores si existen.
IF OBJECT_ID('dbo.transiciones') IS NOT NULL DROP TABLE dbo.transiciones;
IF OBJECT_ID('dbo.simbolos')     IS NOT NULL DROP TABLE dbo.simbolos;
IF OBJECT_ID('dbo.estados')      IS NOT NULL DROP TABLE dbo.estados;

CREATE TABLE dbo.estados (
    id_estado    NVARCHAR(10)  NOT NULL PRIMARY KEY,
    tipo         NVARCHAR(20)  NOT NULL,   -- Inicial | Intermedio | Final | Error
    categoria    NVARCHAR(50)  NULL,       -- CAT del token (NULL si no es final)
    observacion  NVARCHAR(200) NULL
);
CREATE TABLE dbo.simbolos (
    id_simbolo   INT           NOT NULL PRIMARY KEY,
    simbolo      NVARCHAR(10)  NOT NULL UNIQUE
);
CREATE TABLE dbo.transiciones (
    id_estado    NVARCHAR(10)  NOT NULL,
    id_simbolo   INT           NOT NULL,
    destino      NVARCHAR(10)  NOT NULL,
    PRIMARY KEY (id_estado, id_simbolo),
    FOREIGN KEY (id_estado)  REFERENCES dbo.estados(id_estado),
    FOREIGN KEY (id_simbolo) REFERENCES dbo.simbolos(id_simbolo),
    FOREIGN KEY (destino)    REFERENCES dbo.estados(id_estado)
);
GO

